ROOT.proceduredef:
create procedure CDN.SortOrder
as
begin
  set nocount on;

  -- wypełnienie wartosciami (zero pominiete)
  if (select count(*) from CDN.Sort1) <> 255
  begin
    begin transaction;
    delete from CDN.Sort1;
    declare @counter integer;
    set @counter = 1;
    while @counter < 256
    begin
      insert into CDN.Sort1 (num, string) values( @counter, char(@counter) );
      set @counter = @counter + 1;
    end
    commit;
  end

  -- odczytanie kursorem
  declare @znak char(1);
  declare @posortowane varchar(255);
  declare SortOrder cursor local forward_only for
    select string from CDN.Sort1 order by string, num;

  set @posortowane = '';
  open SortOrder;
  fetch next from SortOrder into @znak;
  while @@FETCH_STATUS = 0
  begin
    set @posortowane = @posortowane + @znak;
    fetch next from SortOrder into @znak;
  end
  close SortOrder;

  select @posortowane;
end;
